<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);$studentId=(int)($_GET['id']??0);$pdo=SchoolDatabase::connection();
if(!$studentId){http_response_code(404);exit('Student record not found.');}
if($role==='parent_guardian'&&SchoolAuth::can('portal.child',['student_id'=>$studentId])){$scope='s.id=:student';$params=['student'=>$studentId];}
elseif($role==='student'&&SchoolAuth::can('portal.self',['student_id'=>$studentId])){$scope='s.id=:student AND s.user_id=:user';$params=['student'=>$studentId,'user'=>(int)$user['id']];}
else{http_response_code(403);exit('You are not permitted to view this student record.');}
$q=$pdo->prepare("SELECT s.id,s.admission_number,s.full_name,s.gender,s.admission_date,c.name class_name,y.name year_name FROM students s LEFT JOIN enrollments en ON en.student_id=s.id AND en.status='active' LEFT JOIN class_groups c ON c.id=en.class_group_id LEFT JOIN academic_years y ON y.id=en.academic_year_id WHERE {$scope} LIMIT 1");$q->execute($params);$student=$q->fetch();if(!$student){http_response_code(404);exit('Student record not found.');}
$q=$pdo->prepare("SELECT e.name examination,su.name subject_name,r.mark,a.max_mark,t.name term_name,y.name year_name FROM results r JOIN assessments a ON a.id=r.assessment_id JOIN examinations e ON e.id=a.examination_id JOIN subjects su ON su.id=a.subject_id JOIN terms t ON t.id=e.term_id JOIN academic_years y ON y.id=t.academic_year_id WHERE r.student_id=:student AND r.status='published' ORDER BY y.starts_on DESC,t.starts_on DESC,e.id DESC,su.name");$q->execute(['student'=>$studentId]);$results=$q->fetchAll();
$q=$pdo->prepare("SELECT sess.session_date,sess.period_label,ar.state FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id WHERE ar.student_id=:student ORDER BY sess.session_date DESC LIMIT 40");$q->execute(['student'=>$studentId]);$attendance=$q->fetchAll();
$q=$pdo->prepare("SELECT i.id,i.invoice_number,i.status,i.due_at,t.name term_name,COALESCE((SELECT SUM(ii.amount-ii.discount) FROM invoice_items ii WHERE ii.invoice_id=i.id),0)+COALESCE((SELECT SUM(fa.amount) FROM financial_adjustments fa WHERE fa.invoice_id=i.id),0) total,COALESCE((SELECT SUM(pa.amount) FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.invoice_id=i.id AND p.status='succeeded'),0) paid FROM invoices i JOIN terms t ON t.id=i.term_id WHERE i.student_id=:student AND i.status<>'void' ORDER BY i.id DESC");$q->execute(['student'=>$studentId]);$invoices=$q->fetchAll();
$q=$pdo->prepare("SELECT rc.id,rc.report_number,rc.published_at,t.name term_name,e.name examination,y.name year_name FROM report_cards rc JOIN terms t ON t.id=rc.term_id JOIN examinations e ON e.id=rc.examination_id JOIN academic_years y ON y.id=t.academic_year_id WHERE rc.student_id=:student AND rc.published_at IS NOT NULL ORDER BY rc.published_at DESC");$q->execute(['student'=>$studentId]);$reportCards=$q->fetchAll();
$q=$pdo->prepare("SELECT a.title,a.instructions,a.due_at,a.status,su.name subject_name FROM assignments a JOIN teacher_assignments ta ON ta.id=a.teacher_assignment_id JOIN subjects su ON su.id=ta.subject_id JOIN enrollments en ON en.class_group_id=ta.class_group_id AND en.academic_year_id=ta.academic_year_id WHERE en.student_id=:student AND en.status='active' AND a.status='published' ORDER BY a.due_at DESC LIMIT 50");$q->execute(['student'=>$studentId]);$homework=$q->fetchAll();
$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$schoolRole=$role;$pageTitle='Student record';require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-head"><div><h4><?= e($student['full_name']) ?></h4><p><?= e($student['admission_number'].' · '.($student['class_name']??'Not enrolled').' · '.($student['year_name']??'')) ?></p></div><div class="page-actions"><a class="btn btn-outline-secondary btn-sm" href="<?= SCHOOL_BASE_URL ?>portal/children.php"><i class="bi bi-arrow-left me-1"></i>Back</a></div></div>
<div class="row g-3 mb-3"><div class="col-xl-6"><div class="card h-100"><div class="card-header"><span class="card-title-sm"><i class="bi bi-mortarboard me-1"></i>Published academic results</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Assessment</th><th>Subject</th><th>Term</th><th>Mark</th></tr></thead><tbody><?php foreach($results as $result): ?><tr><td><?= e($result['examination']) ?><div class="small text-muted"><?= e($result['year_name']) ?></div></td><td><?= e($result['subject_name']) ?></td><td><?= e($result['term_name']) ?></td><td><?= e(num($result['mark'])).' / '.e(num($result['max_mark'])) ?></td></tr><?php endforeach; ?><?php if(!$results): ?><tr><td colspan="4" class="text-center text-muted py-3">No results have been published.</td></tr><?php endif; ?></tbody></table></div></div></div>
<div class="col-xl-6"><div class="card h-100"><div class="card-header"><span class="card-title-sm"><i class="bi bi-calendar2-check me-1"></i>Attendance history</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Date</th><th>Session</th><th>Status</th></tr></thead><tbody><?php foreach($attendance as $record): ?><tr><td><?= e(formatDate($record['session_date'])) ?></td><td><?= e($record['period_label']) ?></td><td><span class="badge <?= $record['state']==='present'?'bg-success':'bg-light text-dark' ?>"><?= e(str_replace('_',' ',$record['state'])) ?></span></td></tr><?php endforeach; ?><?php if(!$attendance): ?><tr><td colspan="3" class="text-center text-muted py-3">No attendance has been recorded.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
<div class="card mb-3"><div class="card-header"><span class="card-title-sm"><i class="bi bi-file-earmark-pdf me-1"></i>Published report cards</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Report</th><th>Academic year</th><th>Term</th><th>Published</th><th></th></tr></thead><tbody><?php foreach($reportCards as $card): ?><tr><td><?= e($card['examination']) ?><div class="small text-muted"><?= e($card['report_number']) ?></div></td><td><?= e($card['year_name']) ?></td><td><?= e($card['term_name']) ?></td><td><?= e(formatDate(substr($card['published_at'],0,10))) ?></td><td><a href="<?= SCHOOL_BASE_URL ?>academics/report.php?id=<?= (int)$card['id'] ?>" class="btn btn-sm btn-outline-primary"><i class="bi bi-printer me-1"></i>Print / PDF</a></td></tr><?php endforeach; ?><?php if(!$reportCards): ?><tr><td colspan="5" class="text-center text-muted py-3">No report cards have been published.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="row g-3"><div class="col-xl-7"><div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-receipt me-1"></i>Fee statements</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Invoice</th><th>Term</th><th>Total</th><th>Paid</th><th>Balance</th><th></th></tr></thead><tbody><?php foreach($invoices as $invoice): $balance=max(0,(float)$invoice['total']-(float)$invoice['paid']); ?><tr><td><?= e($invoice['invoice_number']) ?><div class="small text-muted"><?= e(str_replace('_',' ',$invoice['status'])) ?></div></td><td><?= e($invoice['term_name']) ?></td><td><?= e(money($invoice['total'])) ?></td><td><?= e(money($invoice['paid'])) ?></td><td><?= e(money($balance)) ?></td><td><a class="btn btn-sm btn-outline-secondary" href="<?= SCHOOL_BASE_URL ?>finance/receipt.php?invoice_id=<?= (int)$invoice['id'] ?>"><i class="bi bi-printer"></i></a></td></tr><?php endforeach; ?><?php if(!$invoices): ?><tr><td colspan="6" class="text-center text-muted py-3">No invoices are available.</td></tr><?php endif; ?></tbody></table></div></div></div>
<div class="col-xl-5"><div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-journal-text me-1"></i>Homework</span></div><div class="card-body"><?php foreach($homework as $item): ?><div class="border-bottom pb-2 mb-2"><strong><?= e($item['title']) ?></strong><div class="small text-muted"><?= e($item['subject_name']) ?><?= $item['due_at']?' · Due '.e(formatDate(substr($item['due_at'],0,10))):'' ?></div><?php if($item['instructions']): ?><div class="small mt-1"><?= nl2br(e($item['instructions'])) ?></div><?php endif; ?></div><?php endforeach; ?><?php if(!$homework): ?><p class="small text-muted mb-0">No published homework is available.</p><?php endif; ?></div></div></div></div>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
